sp_instance.widget_parameters:
{
	"html": {
		"value": "<style>
    .btn-404 {
        display: inline-block;
        padding: 12px 24px;
        margin: 10px;
        border-radius: 8px;
        text-decoration: none;
        font-weight: bold;
        transition: transform 0.2s ease;
        border: 1px solid transparent;
    }

    .btn-primary-404 {
        background-color: #3b82f6; /* A nice blue */
        color: white;
    }

    .btn-secondary-404 {
        background-color: #e5e7eb; /* A light gray */
        color: #1f2937; /* A dark gray for text */
    }

    .btn-404:hover {
        transform: translateY(-2px);
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    }
</style>
<div style="text-align: center; padding: 40px 20px; font-family: 'Inter', Arial, sans-serif;">
<h1 style="font-size: 3em; color: #1f2937; margin-top: 20px; margin-bottom: 10px;">Oops! Looks like you've ventured off the map.</h1>
<p style="font-size: 1.2em; color: #4b5563; margin-top: 0;">It seems this page has gone off the grid.</p>
<p style="color: #6b7280; max-width: 500px; margin: 20px auto;">We've searched high and low, from server to server, but the page you're looking for is nowhere to be found. Don't worry, here are a couple of safe routes back.</p>
<div><a class="btn-404 btn-primary-404" href="/pm"> Take me Home </a> <a class="btn-404 btn-secondary-404" href="/pm?id=sc_home"> Browse the Service Catalog </a></div>
</div>",
